// Cadence: day0 -> day1 (after 1 day) -> day3 (after 2 more) -> day7 (after 4 more)
// -> day14 (after 7 more) -> monthly (after 16 more, then repeats every 30 days)
const stageOffsetsMs = {
  day0: 1 * 86400000,
  day1: 2 * 86400000,
  day3: 4 * 86400000,
  day7: 7 * 86400000,
  day14: 16 * 86400000,
  monthly: 30 * 86400000
};
const nextStage = { day0: 'day1', day1: 'day3', day3: 'day7', day7: 'day14', day14: 'monthly', monthly: 'monthly' };

const p = $json.properties;
const stage = p.drip_stage || 'day0';
const lastContact = Number(p.last_ai_contact_at) || 0;
const dueAt = lastContact + (stageOffsetsMs[stage] || 86400000);
const isDue = Date.now() >= dueAt;

return { json: {
  contactId: $json.id,
  firstname: p.firstname,
  jobType: p.job_type || 'unknown',
  stage,
  nextStage: nextStage[stage] || 'monthly',
  externalChatId: p.external_chat_id || '',
  phone: p.phone,
  isDue
} };

// Value-first drip content by job type and drip stage. Edit freely - this is the copy.
const isSolar = $json.jobType === 'solar' || $json.jobType === 'solar_battery';
const name = $json.firstname || 'there';

const library = {
  day1: isSolar
    ? `Hi ${name}, quick one - the federal solar rebate (STC) drops in value every 1 Jan as the scheme winds down. Locking in this year keeps the current discount. Happy to run your numbers, no pressure.`
    : `Hi ${name}, just following up - happy to answer any questions on your roof job whenever you're ready. No rush.`,
  day3: isSolar
    ? `A lot of our solar customers pair the system with a Brighte or Plenti payment plan so there's no big upfront cost. Want me to send how that works?`
    : `Most of our jobs are done in a day or two once booked. If a rough quote would help you plan, just say the word.`,
  day7: isSolar
    ? `Case study: a customer in a similar postcode cut their power bill by ~70% with a 6.6kW system. Want a free estimate for your place?`
    : `Storm season's a good reminder to check your roof before it becomes an emergency. Want a free inspection booked in?`,
  day14: `Still here whenever you're ready ${name} - no pressure at all. Feel free to message any time.`,
  monthly: isSolar
    ? `Checking in ${name} - the STC rebate steps down again on 1 Jan. If solar's still on your radar, worth locking in before then.`
    : `Just checking in ${name} - let us know if your roofing plans have moved forward and we'll get a quote sorted.`
};

return { json: { ...$json, text: library[$json.stage] || library.monthly } };

const channel = ($json.externalChatId || '').split(':')[0] || 'none';
const id = ($json.externalChatId || '').split(':')[1] || '';
return { json: { ...$json, channel, id } };
